def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - add empty field if we just saw a comma
            if fields or i > 0 and line[i-1] == ',':
                fields.append('')
            break

        if line[i] == ',':
            # Empty field before comma
            fields.append('')
            i += 1
        elif line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    i += 1
                    if i < len(line) and line[i] == '"':
                        # Doubled quote
                        field += '"'
                        i += 1
                    else:
                        # End of quoted field
                        if i == len(line) or line[i] == ',':
                            fields.append(field)
                            if i < len(line):
                                i += 1  # Skip the comma
                            break
                        else:
                            # Character after closing quote is not comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

